{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/metric-row.json
    Dashboard counters in a row or a grid: tiles with an icon, a number and a caption, or compact figures. Axes: columns (2, 4), item (tile, compact), tone (default, muted), density (default, compact).
    Props (p): id, title, metrics, cols, item, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_metrics = ($p['metrics'] ?? null)}
{var $v_cols = ($p['cols'] ?? '4')}
{var $v_item = ($p['item'] ?? 'tile')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_8}
  {capture $c_7}
    {foreach ui_l($v_metrics) as $v_m}
      {if ui_t(ui_eq($v_item, 'tile'))}
        {capture $c_1}
          {=ui_include('blocks/stat-tile.latte', ['p' => ['label' => ui_get($v_m, ['label']), 'value' => ui_get($v_m, ['value']), 'icon' => ui_get($v_m, ['icon']), 'hint' => ui_get($v_m, ['hint'])]])|noescape}
        {/capture}
        {=ui_include('ui/box/box.latte', ['p' => ['Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_1])|noescape}
      {else}
        {capture $c_6}
          {capture $c_3}
            {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_m, ['icon'])), 'Size' => 16]])|noescape}
            {capture $c_2}
              {=ui_text(ui_get($v_m, ['label']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs'], 'children' => $c_2])|noescape}
          {/capture}
          {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center', 'Class' => 'text-muted-foreground'], 'children' => $c_3])|noescape}
          {capture $c_4}
            {=ui_text(ui_get($v_m, ['value']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => '2xl', 'Weight' => 'bold'], 'children' => $c_4])|noescape}
          {capture $c_5}
            {=ui_text(ui_get($v_m, ['hint']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_5])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0', 'Class' => 'rounded bg-card p-4 inset-ring inset-ring-border', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_6])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_cols, '2')) ? '1-2' : '1-4')), 'Class' => 'gap-4', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_7])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_8])|noescape}
